 final match=(category==''||category=='Refeições')&&'casa do smash duplo smash hambúrgueres'.contains(query.trim().toLowerCase());
 final nav=NavigationBar(selectedIndex:tab,onDestinationSelected:select,destinations:const [NavigationDestination(icon:Icon(Icons.home),label:'Início'),NavigationDestination(icon:Icon(Icons.search),label:'Explorar'),NavigationDestination(icon:Icon(Icons.receipt_long),label:'Pedidos'),NavigationDestination(icon:Icon(Icons.person),label:'Perfil')]);
 if(tab==2)return PageBody([title('Meus pedidos'),const OrderList()],bottom:nav);
 if(tab==3)return PageBody([title('Perfil'),gap(),panel(ListTile(leading:const Icon(Icons.person),title:Text(api.name))),gap(),action('Sair',(){api.token='';Navigator.pushReplacement(c,MaterialPageRoute(builder:(_)=>const AuthScreen()));})],bottom:nav);
 return PageBody([Row(children:[Expanded(child:title('EYI Food',36)),IconButton.filledTonal(onPressed:()=>select(2),icon:const Icon(Icons.notifications_outlined))]),const Text('Peça sua comida favorita'),gap(),const Align(alignment:Alignment.centerLeft,child:Chip(avatar:Icon(Icons.location_on),label:Text('Ibiporã PR'))),gap(),TextField(controller:search,onChanged:(v)=>setState(()=>query=v),decoration:InputDecoration(filled:true,fillColor:grey,prefixIcon:const Icon(Icons.search),hintText:'Busque por restaurantes, pratos…',border:OutlineInputBorder(borderRadius:BorderRadius.circular(28),borderSide:BorderSide.none))),gap(18),Row(children:[Expanded(child:title('Categorias')),TextButton(onPressed:()=>setState((){category='';query='';search.clear();}),child:const Text('Ver todas ❯'))]),gap(),Row(children:[for(final item in [('Refeições',Icons.restaurant),('Pizzas',Icons.local_pizza),('Sorvetes',Icons.icecream)])Expanded(child:Padding(padding:const EdgeInsets.all(3),child:InkWell(onTap:()=>setState(()=>category=category==item.$1?'':item.$1),child:panel(Column(children:[Icon(item.$2,size:32),gap(5),Text(item.$1)]),color:category==item.$1?const Color(0xffffdddd):grey,pad:10))))]),gap(),const Divider(),gap(),title(tab==0?'Destaque em Ibiporã':'Explorar restaurantes'),const Text('Restaurantes que você vai adorar'),gap(),if(!match)panel(const Text('Nenhum restaurante encontrado.')) else panel(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[photo('featured',135),gap(),Row(children:[Expanded(child:title('Casa do Smash')),const Chip(label:Text('★ 4,8'))]),const Text('Hambúrgueres artesanais smash'),gap(),pair('🛵  Entrega: R\$ 5,00','◷  30–45 min'),gap(),action('Fazer pedido  →',()=>open(c,const Product()))]),pad:9)],bottom:nav);
 }}
class Product extends StatefulWidget{const Product({super.key});@override State<Product> createState()=>_Product();}
class _Product extends State<Product>{
 int qty=1;bool liked=false;final selected=<String>{};
 @override Widget build(BuildContext c)=>PageBody([title('EYI Food',32),gap(),panel(backTitle(c,'Casa do Smash'),pad:7),const Text('    📍 Ibiporã PR       •       Entrega R\$ 5,00'),gap(),Stack(children:[photo('smash',185),Positioned(right:8,top:8,child:IconButton.filledTonal(onPressed:()=>setState(()=>liked=!liked),icon:Icon(liked?Icons.favorite:Icons.favorite_border,color:liked?red:ink)))]),gap(),Row(children:[Expanded(child:title('Duplo Smash',30)),Chip(label:Text(money(3290)))]),const Text('Dois smash burgers de carne bovina (100 g cada), com queijo cheddar, molho da casa e pão brioche macio.'),const Divider(),title('Adicionais'),gap(),panel(Column(children:extras.entries.map((e)=>CheckboxListTile(dense:true,contentPadding:EdgeInsets.zero,controlAffinity:ListTileControlAffinity.leading,value:selected.contains(e.key),onChanged:(v)=>setState(()=>v==true?selected.add(e.key):selected.remove(e.key)),title:Text(e.key),secondary:Text('+ ${money(e.value)}'))).toList()),pad:8),gap(),Row(children:[Expanded(child:title('Quantidade',20)),IconButton(onPressed:qty>1?()=>setState(()=>qty--):null,icon:const Icon(Icons.remove)),Text('$qty'),IconButton(onPressed:qty<20?()=>setState(()=>qty++):null,icon:const Icon(Icons.add))]),gap(),action('Adicionar à sacola',()=>open(c,Checkout(qty,selected.toList())),icon:Icons.shopping_bag_outlined)]);
}
class Checkout extends StatefulWidget{
 final int qty;final List<String> selected;const Checkout(this.qty,this.selected,{super.key});
 @override State<Checkout> createState()=>_Checkout();
}
class _Checkout extends State<Checkout>{
 String payment='Pix',address='';bool busy=false;final key=requestId();
 Future<void> edit()async{String value=address;final result=await showDialog<String>(context:context,builder:(c)=>AlertDialog(title:const Text('Endereço de entrega'),content:TextFormField(initialValue:value,autofocus:true,onChanged:(v)=>value=v,decoration:const InputDecoration(hintText:'Rua, número e bairro')),actions:[TextButton(onPressed:()=>Navigator.pop(c,value.trim()),child:const Text('Salvar'))]));if(result!=null&&mounted)setState(()=>address=result);}
 Future<void> confirm()async{if(address.isEmpty){await edit();return;}setState(()=>busy=true);try{final order=await api.call('/orders',{'quantity':widget.qty,'extras':widget.selected,'address':address,'payment':payment,'request_id':key});if(mounted)Navigator.pushAndRemoveUntil(context,MaterialPageRoute(builder:(_)=>Tracking(order)),(route)=>route.isFirst);}catch(e){if(mounted)notice(context,e.toString());}finally{if(mounted)setState(()=>busy=false);}}
 @override Widget build(BuildContext c){final subtotal=widget.qty*(3290+widget.selected.fold<int>(0,(s,e)=>s+extras[e]!));return PageBody([backTitle(c,'EYI Food'),gap(),title('Checkout',34),const Text('Revise seu pedido e confirme a compra.'),gap(),panel(const ListTile(leading:Icon(Icons.storefront),title:Text('Casa do Smash'),subtitle:Text('Ibiporã PR'))),gap(),title('Seu pedido'),gap(),panel(Row(children:[SizedBox(width:80,child:photo('smash',60)),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[title('${widget.qty}× Duplo Smash',18),Text(widget.selected.isEmpty?'Sem adicionais':widget.selected.join(', '))])),Text(money(subtotal))])),gap(),panel(ListTile(onTap:edit,leading:const Icon(Icons.location_on,color:red),title:const Text('Endereço de entrega'),subtitle:Text(address.isEmpty?'Informar endereço em Ibiporã':address),trailing:const Icon(Icons.edit)),pad:0),gap(),title('Forma de pagamento'),for(final p in ['Pix','Cartão'])Padding(padding:const EdgeInsets.only(top:8),child:panel(ListTile(onTap:()=>setState(()=>payment=p),leading:Icon(p=='Pix'?Icons.pix:Icons.credit_card),title:Text(p),subtitle:Text(p=='Pix'?'Pagamento instantâneo':'Crédito ou débito'),trailing:Icon(payment==p?Icons.check_circle:Icons.circle_outlined)),pad:0)),gap(),panel(Column(crossAxisAlignment:CrossAxisAlignment.start,children:[title('Resumo do pedido',20),pair('Duplo Smash',money(subtotal)),pair('Entrega',money(500)),const Divider(),pair('Total',money(subtotal+500))])),gap(),action(busy?'Confirmando…':'Confirmar pedido',busy?null:confirm,icon:Icons.shopping_cart)]);}
}
